	hullWidth: number;
	onFire: boolean;
	fireDOTTimer: number;
	fireParticles: Mesh[];
}

interface CannonballData {
	mesh: Mesh;
	vx: number;
	vy: number;
	vz: number;
	damage: number;
	isEnemy: boolean;
	lifetime: number;
	maxLifetime: number;
